import React from 'react';
import {
  IncidentPublicReport,
  IncidentPublicReportStatus,
} from '../../../models/IncidentPublicReport';
import { useResponsive } from '../../../hooks/useResponsive';
import styles from './PublicReportTable.module.css';
import { Button, TwoLineTable, TwoLineTableColumn, TwoLineTableRow } from '@linm-soft-org/linm-web-common-components';

interface Props {
  items: IncidentPublicReport[];
  loading?: boolean;
  guest?: boolean;
  onView: (item: IncidentPublicReport) => void;
  label: (key: string) => string;
  statusLabel: (status: string) => string;
}

const BADGE_CLS: Record<string, string> = {
  [IncidentPublicReportStatus.Submitted]: styles.badgeSubmitted,
  [IncidentPublicReportStatus.Confirmed]: styles.badgeConfirmed,
  [IncidentPublicReportStatus.Rejected]: styles.badgeRejected,
};

const fmt = (iso: string | null | undefined) =>
  iso
    ? new Date(iso).toLocaleString('vi-VN', {
      day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit',
    })
    : '—';

export const PublicReportTable: React.FC<Props> = ({
  items, loading, guest, onView, label, statusLabel,
}) => {
  const { isMobile } = useResponsive();

  const columns: TwoLineTableColumn[] = guest
    ? [
      { key: 'createdAt', label: label('colCreatedAt'), width: '25%' },
      { key: 'patient', label: label('colPatient'), width: '25%' },
      { key: 'department', label: label('colDepartment'), width: '25%' },
      { key: 'status', label: label('colStatus'), width: '25%' },
    ]
    : [
      { key: 'createdAt', label: label('colCreatedAt'), width: '18%' },
      { key: 'patient', label: label('colPatient'), width: '18%' },
      { key: 'department', label: label('colDepartment'), width: '18%' },
      { key: 'phone', label: label('colPhone'), width: '16%' },
      { key: 'status', label: label('colStatus'), width: '15%' },
      { key: 'device', label: label('colDevice'), width: '15%' },
    ];

  const rows: TwoLineTableRow<IncidentPublicReport>[] = items.map((item) => ({
    id: item.id,
    data: item,
    idElement: <span className={styles.idCode}>{item.idCode}</span>,
    line1Content: (
      <>
        <span className={styles.desc}>{item.description || <em className={styles.na}>—</em>}</span>
        <span className={`${styles.badge} ${BADGE_CLS[item.status] ?? styles.badgeSubmitted}`}>
          {statusLabel(item.status)}
        </span>
      </>
    ),
    line2Cells: guest
      ? [
        <span>{fmt(item.createdAt)}</span>,
        <span>{item.patientName || <em className={styles.na}>—</em>}</span>,
        <span>{item.departmentName || <em className={styles.na}>—</em>}</span>,
        <span>{statusLabel(item.status)}</span>,
      ]
      : [
        <span>{fmt(item.createdAt)}</span>,
        <span>{item.patientName || <em className={styles.na}>—</em>}</span>,
        <span>{item.departmentName || <em className={styles.na}>—</em>}</span>,
        <span>{item.reporterPhone || <em className={styles.na}>—</em>}</span>,
        <span>{statusLabel(item.status)}</span>,
        <span>{item.deviceId || <em className={styles.na}>—</em>}</span>,
      ],
    actionsContent: (
      <div className={styles.actions}>
        <Button variant="secondary" onClick={() => onView(item)}>
          <i className="fas fa-eye" /> {label('view')}
        </Button>
      </div>
    ),
  }));

  return (
    <TwoLineTable
      columns={columns}
      rows={rows}
      loading={loading}
      emptyMessage={{
        icon: 'fas fa-qrcode',
        title: label('emptyTitle'),
        description: guest ? label('emptyDesc') : label('emptyStaff'),
      }}
      expandableActions
      isMobile={isMobile}
    />
  );
};
