import React, { useEffect, useState } from 'react';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchIncidentPublicReports,
  fetchIncidentPublicReportStats,
  setFilters,
  setPage,
} from '../../store/slices/incidentPublicReportsSlice';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import { useResponsive } from '../../hooks/useResponsive';
import { useFormOptions } from '../../hooks/useFormOptions';
import { useIncidentPublicReportPermissions } from '../../hooks/useIncidentPublicReportPermissions';
import { incidentPublicReportService } from '../../services/incidentPublicReports';
import type { IncidentPublicReport, IncidentPublicReportFilters, IncidentPublicReportPoster } from '../../models/IncidentPublicReport';
import { PublicReportStatsCards } from './components/PublicReportStatsCards';
import { PublicReportFiltersBar } from './components/PublicReportFiltersBar';
import { PublicReportTable } from './components/PublicReportTable';
import { PublicReportQrModal } from './components/PublicReportQrModal';
import {
  printPublicReportPoster,
  publicReportAbsoluteUrl,
  publicReportQrImageUrl,
} from './printPublicReportPoster';
import styles from '../IncidentDetectionListPage/IncidentDetectionListPage.module.css';
import { Button, TableCard, Pagination } from '@linm-soft-org/linm-web-common-components';
import { ErpFilterCardHeader } from '../../components/layout/ErpFilterCardHeader';
import { getApiErrorMessage } from '../../utils/apiMessages';
import { addToast } from '../../store/slices/uiSlice';

const IncidentPublicReportListPage: React.FC = () => {
  const appNavigate = useAppNavigate();
  const dispatch = useAppDispatch();
  const { isMobile } = useResponsive();
  const { publicReportLabel: L, publicReportStatusOptions } = useFormOptions('public-report-list');
  const { canRead, canPrint } = useIncidentPublicReportPermissions();
  const { items, loading, filters, pagination, stats } = useAppSelector((s) => s.incidentPublicReports);
  const showLoading = useMinLoadingTime(loading);
  const [poster, setPoster] = useState<IncidentPublicReportPoster | null>(null);
  const [qrOpen, setQrOpen] = useState(false);

  const statusLabel = (status: string) =>
    publicReportStatusOptions.find((o) => o.value === status)?.label ?? status;

  useEffect(() => {
    const t = setTimeout(() => { dispatch(fetchIncidentPublicReports()); }, 0);
    return () => clearTimeout(t);
  }, [dispatch, filters, pagination.page]);

  useEffect(() => {
    const t = setTimeout(() => { dispatch(fetchIncidentPublicReportStats()); }, 0);
    return () => clearTimeout(t);
  }, [dispatch]);

  const handleFilterChange = (f: IncidentPublicReportFilters) => {
    dispatch(setFilters(f));
    dispatch(setPage(1));
  };

  const handleClearFilters = () => {
    dispatch(setFilters({}));
    dispatch(setPage(1));
  };

  const loadPoster = async () => {
    try {
      const data = await incidentPublicReportService.poster();
      setPoster(data);
      return data;
    } catch (error: unknown) {
      dispatch(addToast({ message: getApiErrorMessage(error), type: 'error' }));
      return null;
    }
  };

  const handleQr = async () => {
    const data = poster ?? await loadPoster();
    if (data) setQrOpen(true);
  };

  const handlePrint = async () => {
    const data = poster ?? await loadPoster();
    if (!data) return;
    printPublicReportPoster(data, { title: L('posterTitle'), hint: L('posterHint') });
  };

  const handleView = (item: IncidentPublicReport) =>
    appNavigate(scykRoutes.publicReports.detail(item.id));

  if (!canRead) return null;

  const publicUrl = poster ? publicReportAbsoluteUrl(poster) : '';

  return (
    <div className={styles.page} data-catalog-list-page data-lin-list-layout="erp-filter-bar" data-testid="incident-public-report-list">
      <div className={styles.pageHeader}>
        <h1 className={styles.title}>
          <i className="fas fa-qrcode" />
          {!isMobile && ` ${L('staffTitle')}`}
        </h1>
        <div className={styles.headerActions}>
          {canPrint && (
            <>
              <Button variant="secondary" onClick={handleQr} data-testid="incident-public-report-qr">
                <i className="fas fa-qrcode" />
                {!isMobile && ` ${L('qr')}`}
              </Button>
              <Button variant="secondary" onClick={handlePrint} data-testid="incident-public-report-print">
                <i className="fas fa-print" />
                {!isMobile && ` ${L('print')}`}
              </Button>
            </>
          )}
        </div>
      </div>

      <PublicReportStatsCards stats={stats} loading={showLoading} label={L} statusLabel={statusLabel} />

      <TableCard
        header={
          <ErpFilterCardHeader title={L('listCard')} testIdPrefix="incident-public-report">
            <PublicReportFiltersBar
              filters={filters}
              onChange={handleFilterChange}
              onClear={handleClearFilters}
              loading={showLoading}
            />
          </ErpFilterCardHeader>
        }
        footer={
          <Pagination
            currentPage={pagination.page}
            totalPages={Math.ceil(Math.max(pagination.totalCount, 1) / pagination.pageSize)}
            totalCount={pagination.totalCount}
            pageSize={pagination.pageSize}
            onPageChange={(p) => dispatch(setPage(p))}
          />
        }
      >
        <PublicReportTable
          items={items}
          loading={showLoading}
          onView={handleView}
          label={L}
          statusLabel={statusLabel}
        />
      </TableCard>

      {qrOpen && poster && (
        <PublicReportQrModal
          poster={poster}
          qrUrl={publicReportQrImageUrl(publicUrl)}
          publicUrl={publicUrl}
          label={L}
          onClose={() => setQrOpen(false)}
          onPrint={handlePrint}
        />
      )}
    </div>
  );
};

export default IncidentPublicReportListPage;
