import React from 'react';
import { IncidentPublicReportStats } from '../../../models/IncidentPublicReport';
import { StatsCardsGrid, StatsCard } from '@linm-soft-org/linm-web-common-components';

interface Props {
  stats: IncidentPublicReportStats;
  loading?: boolean;
  label: (key: string) => string;
  statusLabel: (status: string) => string;
}

export const PublicReportStatsCards: React.FC<Props> = ({ stats, loading, label, statusLabel }) => (
  <StatsCardsGrid>
    <StatsCard label={label('statsTotal')} value={stats.total} icon="fas fa-qrcode" variant="primary" loading={loading} />
    <StatsCard label={statusLabel('submitted')} value={stats.submitted} icon="fas fa-inbox" variant="warning" loading={loading} />
    <StatsCard label={statusLabel('confirmed')} value={stats.confirmed} icon="fas fa-check-circle" variant="success" loading={loading} />
    <StatsCard label={statusLabel('rejected')} value={stats.rejected} icon="fas fa-times-circle" variant="gray" loading={loading} />
  </StatsCardsGrid>
);
